import type { NextConfig } from "next";
import { readFileSync } from "fs";
import { join } from "path";

/**
 * Permanent redirects for migrated slugs.
 *
 * The old slugs were cut mid-word by the importer's 80-char truncation
 * (…quartz-wrist-, …daily-wear-stret). They were migrated to clean
 * word-boundary slugs, and every one of them must 301 or the handful of
 * rankings those URLs hold is lost.
 *
 * The mapping is generated by `node scripts/migrate-slugs.mjs --apply` and kept
 * in a file rather than inlined here: the URLs are long and near-identical, so
 * hand-copying them is exactly how a redirect ends up pointing at the wrong
 * product. The build fails loudly if the file is missing.
 */
const redirectsFile = join(process.cwd(), "scripts", "slug-redirects.json");

type SlugRedirect = { source: string; destination: string; statusCode: number };

function loadSlugRedirects(): SlugRedirect[] {
  try {
    return JSON.parse(readFileSync(redirectsFile, "utf-8")) as SlugRedirect[];
  } catch (err) {
    throw new Error(
      `Could not read slug redirects from ${redirectsFile}. ` +
        `Restore it from git, or regenerate with "node scripts/migrate-slugs.mjs". ` +
        `Cause: ${(err as Error).message}`
    );
  }
}

const nextConfig: NextConfig = {
  images: {
    unoptimized: true,
  },
  trailingSlash: true,

  async redirects() {
    return loadSlugRedirects();
  },
};

export default nextConfig;
